func TestTOMLLoaderWpIgnoreInactive(t *testing.T) {
	previous := Conf
	defer func() { Conf = previous }()

	dir, err := ioutil.TempDir("", "vuls-wp-ignore-inactive-")
	if err != nil {
		t.Fatal(err)
	}
	defer os.RemoveAll(dir)

	tests := []struct {
		name      string
		tomlValue string
		cliValue  bool
		want      bool
	}{
		{name: "enabled by config", tomlValue: "true", want: true},
		{name: "disabled by config", tomlValue: "false", want: false},
		{name: "CLI true survives config false", tomlValue: "false", cliValue: true, want: true},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			Conf = Config{WpIgnoreInactive: tt.cliValue}
			path := filepath.Join(dir, "config.toml")
			if err := ioutil.WriteFile(path, []byte("wpIgnoreInactive = "+tt.tomlValue+"\n"), 0600); err != nil {
				t.Fatal(err)
			}
			if err := (TOMLLoader{}).Load(path, ""); err != nil {
				t.Fatal(err)
			}
			if Conf.WpIgnoreInactive != tt.want {
				t.Errorf("WpIgnoreInactive = %t, want %t", Conf.WpIgnoreInactive, tt.want)
			}
		})
	}
}

func TestToCpeURI(t *testing.T) {
	var tests = []struct {
		in       string
		expected string
		err      bool
	}{
		{
			in:       "",
			expected: "",
			err:      true,
		},
		{
			in:       "cpe:/a:microsoft:internet_explorer:10",
			expected: "cpe:/a:microsoft:internet_explorer:10",
			err:      false,
		},
		{
			in:       "cpe:2.3:a:microsoft:internet_explorer:10:*:*:*:*:*:*:*",
			expected: "cpe:/a:microsoft:internet_explorer:10",
			err:      false,
		},
	}

	for i, tt := range tests {
		actual, err := toCpeURI(tt.in)
		if err != nil && !tt.err {
			t.Errorf("[%d] unexpected error occurred, in: %s act: %s, exp: %s",
				i, tt.in, actual, tt.expected)
		} else if err == nil && tt.err {
			t.Errorf("[%d] expected error is not occurred, in: %s act: %s, exp: %s",
				i, tt.in, actual, tt.expected)
		}
		if actual != tt.expected {
			t.Errorf("[%d] in: %s, actual: %s, expected: %s",
				i, tt.in, actual, tt.expected)
		}
	}
